template.inlineTemplate:
# creating a copy of the server.env to work on, otherwise the sed command does not work cp ${instance-SERVER_DIRECTORY}/server.env ${instance-SERVER_DIRECTORY}/server.env_temp
sed "s#^[ \#]*SAF_UNAUTHENTICATED_USER_ID=.*#SAF_UNAUTHENTICATED_USER_ID=${instance-WLP_UNAUTHENTICATED_USER}#g" ${instance-SERVER_DIRECTORY}/server.env_temp > ${instance-SERVER_DIRECTORY}/server.env;
# deleting the copy rm ${instance-SERVER_DIRECTORY}/server.env_temp

# creating a copy of the server.env to work on, otherwise the sed command does not work
cp ${instance-SERVER_DIRECTORY}/server.env ${instance-SERVER_DIRECTORY}/server.env_temp

sed "s#^[ \#]*TLS_KEY_STORE_SERVER_CERT=.*#TLS_KEY_STORE_SERVER_CERT=${instance-SERVER_TLS_KEY_STORE_SERVER_CERT}#g;
    s#^[ \#]*OIDC_PROVIDER_TRUST_ALIAS_NAME=.*#OIDC_PROVIDER_TRUST_ALIAS_NAME=${instance-SERVER_OIDC_PROVIDER_CERT}#g;
    s#^[ \#]*OIDC_PROVIDER_KEY_ALIAS_NAME=.*#OIDC_PROVIDER_KEY_ALIAS_NAME=${instance-SERVER_OIDC_PROVIDER_CERT}#g" ${instance-SERVER_DIRECTORY}/server.env_temp > ${instance-SERVER_DIRECTORY}/server.env;

# deleting the copy
rm ${instance-SERVER_DIRECTORY}/server.env_temp

# creating a copy of the server.env to work on, otherwise the sed command does not work cp ${instance-SERVER_DIRECTORY}/server.env ${instance-SERVER_DIRECTORY}/server.env_temp
sed "s#JAVA_HOME=.*#JAVA_HOME=${instance-JAVA_HOME}#g" ${instance-SERVER_DIRECTORY}/server.env_temp > ${instance-SERVER_DIRECTORY}/server.env;
# deleting the copy rm ${instance-SERVER_DIRECTORY}/server.env_temp

# creating a copy of the server.env to work on, otherwise the sed command does not work
cp ${instance-SERVER_DIRECTORY}/server.env ${instance-SERVER_DIRECTORY}/server.env_temp

sed "s#^[ \#]*DB2_LIBPATH=.*#DB2_LIBPATH=${instance-DB_LIBPATH}#g;
    s#^[ \#]*DB_LIBPATH=.*#DB_LIBPATH=${instance-DB_LIBPATH}#g;
    s#^[ \#]*DB2_CLASSPATH=.*#DB2_CLASSPATH=${instance-DB_CLASSPATH}#g;
    s#^[ \#]*DB_CLASSPATH=.*#DB_CLASSPATH=${instance-DB_CLASSPATH}#g" ${instance-SERVER_DIRECTORY}/server.env_temp > ${instance-SERVER_DIRECTORY}/server.env;

# deleting the copy
rm ${instance-SERVER_DIRECTORY}/server.env_temp
